(1, '2018-08-07 00:26:22', '2018-08-07 00:26:22', '215B68E72EEA0E23BAVZVSHGC0NSMP1PKO9OCAM1RUVF10FQGZ', 'deposito', 0, NULL, NULL, NULL, NULL, NULL, 0, 1),
